raw.css:
:root {
  --color-primary: #2d5016;
  --color-primary-dark: #1f3810;
  --color-accent: #e8d4c4;
  --color-accent-on-dark: #f5e6dd;
  --color-text: #2b2b2b;
  --color-text-light: #6b6b6b;
  --color-bg: #fafbf8;
  --color-border: #d4ccc0;
  --color-success: #4a7c59;
  --color-white: #ffffff;
  --font-serif: Georgia, "Times New Roman", serif;
  --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Arial, sans-serif;
  --spacing-unit: 1rem;
  --spacing-s: calc(var(--spacing-unit) * 0.5);
  --spacing-m: var(--spacing-unit);
  --spacing-l: calc(var(--spacing-unit) * 2);
  --spacing-xl: calc(var(--spacing-unit) * 3);
  --spacing-2xl: calc(var(--spacing-unit) * 4);
  --shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px rgba(0, 0, 0, 0.1);
  --shadow-lg: 0 10px 20px rgba(0, 0, 0, 0.15);
  --transition: all 0.3s ease;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-sans);
  color: var(--color-text);
  background-color: var(--color-bg);
  line-height: 1.6;
  font-size: 1rem;
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-serif);
  font-weight: 600;
  line-height: 1.3;
  margin-bottom: var(--spacing-m);
  color: var(--color-primary-dark);
}

h1 { font-size: clamp(2rem, 5vw, 3.5rem); }
h2 { font-size: clamp(1.75rem, 4vw, 2.75rem); }
h3 { font-size: clamp(1.25rem, 3vw, 1.75rem); }
h4 { font-size: 1.25rem; }
h5 { font-size: 1.1rem; }
h6 { font-size: 1rem; }

p {
  margin-bottom: var(--spacing-m);
}

a {
  color: var(--color-primary);
  text-decoration: none;
  transition: var(--transition);
}

a:hover {
  color: var(--color-primary-dark);
  text-decoration: underline;
}

a:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
  border-radius: 2px;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 var(--spacing-m);
}

header.site-header {
  background-color: var(--color-white);
  border-bottom: 1px solid var(--color-border);
  position: sticky;
  top: 0;
  z-index: 100;
  box-shadow: var(--shadow-sm);
}

header.site-header .container {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: var(--spacing-m);
  padding-bottom: var(--spacing-m);
  flex-wrap: wrap;
  gap: var(--spacing-m);
}

.logo {
  font-family: "Palatino Linotype", "Book Antiqua", serif;
  font-size: clamp(1.3rem, 4vw, 1.6rem);
  font-weight: 400;
  font-variant: small-caps;
  letter-spacing: 0.15em;
  color: var(--color-primary-dark);
  border-bottom: 2px solid var(--color-accent);
  padding-bottom: 0.25rem;
  white-space: nowrap;
}

.logo:hover {
  color: var(--color-primary);
  text-decoration: none;
}

.logo:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

header nav {
  display: flex;
  gap: var(--spacing-l);
  flex-wrap: wrap;
}

header nav a {
  display: inline-block;
  padding: var(--spacing-s) var(--spacing-m);
  color: var(--color-text);
  font-weight: 500;
  transition: var(--transition);
  border-bottom: 2px solid transparent;
}

header nav a:hover {
  color: var(--color-primary);
  border-bottom-color: var(--color-accent);
  text-decoration: none;
}

header nav a:focus {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}

footer.site-footer {
  background-color: var(--color-primary-dark);
  color: var(--color-accent-on-dark);
  padding: var(--spacing-2xl) var(--spacing-m);
  margin-top: var(--spacing-2xl);
}

footer.site-footer .container {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--spacing-xl);
  align-items: start;
}

footer.site-footer .footer-content {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-l);
}

footer.site-footer p {
  margin-bottom: 0;
  font-size: 0.95rem;
  line-height: 1.8;
}

footer.site-footer a {
  color: var(--color-accent-on-dark);
}

footer.site-footer a:hover {
  color: var(--color-white);
}

footer.site-footer .footer-copyright {
  text-align: center;
  grid-column: 1 / -1;
  font-size: 0.85rem;
  color: rgba(245, 230, 221, 0.7);
  border-top: 1px solid rgba(245, 230, 221, 0.2);
  padding-top: var(--spacing-l);
}

button, input[type="submit"], input[type="reset"], input[type="button"], .btn {
  display: inline-block;
  padding: var(--spacing-m) var(--spacing-l);
  min-height: 44px;
  min-width: 44px;
  background-color: var(--color-primary-dark);
  color: var(--color-white);
  border: none;
  border-radius: 4px;
  font-family: var(--font-sans);
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: var(--transition);
  text-decoration: none;
  text-align: center;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

button:hover, .btn:hover {
  background-color: var(--color-primary);
}

button:focus, .btn:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

button:active, .btn:active {
  transform: scale(0.98);
}

input[type="text"],
input[type="email"],
input[type="tel"],
input[type="password"],
input[type="date"],
input[type="time"],
input[type="number"],
select,
textarea {
  display: block;
  width: 100%;
  padding: var(--spacing-m);
  margin-bottom: var(--spacing-m);
  border: 1px solid var(--color-border);
  border-radius: 4px;
  font-family: var(--font-sans);
  font-size: 1rem;
  background-color: var(--color-white);
  color: var(--color-text);
  transition: var(--transition);
  min-height: 44px;
}

input[type="text"]:focus,
input[type="email"]:focus,
input[type="tel"]:focus,
input[type="password"]:focus,
input[type="date"]:focus,
input[type="time"]:focus,
input[type="number"]:focus,
select:focus,
textarea:focus {
  outline: 2px solid var(--color-accent);
  outline-offset: 1px;
  border-color: var(--color-primary);
}

label {
  display: block;
  margin-bottom: var(--spacing-s);
  font-weight: 600;
  color: var(--color-text);
}

textarea {
  resize: vertical;
  min-height: 120px;
}

.card {
  background-color: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: 8px;
  padding: var(--spacing-l);
  transition: var(--transition);
  box-shadow: var(--shadow-sm);
}

.card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-4px);
}

.grid {
  display: grid;
  gap: var(--spacing-l);
  margin-bottom: var(--spacing-xl);
}

.grid--2col {
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
}

.grid--3col {
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
}

section {
  padding: var(--spacing-2xl) 0;
}

main {
  min-height: calc(100vh - 300px);
}

img {
  max-width: 100%;
  height: auto;
  display: block;
  border-radius: 4px;
}

@media (max-width: 600px) {
  :root {
    --spacing-unit: 0.9rem;
  }

  header.site-header .container {
    flex-direction: column;
    align-items: flex-start;
    padding-top: var(--spacing-m);
    padding-bottom: var(--spacing-m);
  }

  .logo {
    font-size: 1.2rem;
  }

  header nav {
    width: 100%;
    gap: var(--spacing-m);
    flex-direction: column;
  }

  header nav a {
    padding: 0.6rem var(--spacing-s);
    font-size: 0.95rem;
  }

  footer.site-footer .container {
    grid-template-columns: 1fr;
    gap: var(--spacing-l);
  }

  .grid--2col,
  .grid--3col {
    grid-template-columns: 1fr;
  }

  section {
    padding: var(--spacing-xl) 0;
  }

  h1 { font-size: 1.75rem; }
  h2 { font-size: 1.5rem; }
  h3 { font-size: 1.2rem; }

  button, .btn, input[type="submit"] {
    width: 100%;
  }
}

@media (min-width: 601px) {
  header nav {
    margin-left: auto;
  }
}

@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

pages.css:
.index-hero {
  background: linear-gradient(135deg, var(--color-primary-dark) 0%, var(--color-primary) 100%);
  color: var(--color-accent-on-dark);
  padding: var(--spacing-2xl) 0;
}

.index-hero .container {
  display: flex;
  align-items: center;
  gap: var(--spacing-2xl);
}

.index-hero-content {
  flex: 1;
}

.index-hero h1 {
  color: var(--color-accent-on-dark);
  margin-bottom: var(--spacing-l);
}

.index-hero-tagline {
  font-size: 1.15rem;
  color: var(--color-accent-on-dark);
  margin-bottom: var(--spacing-l);
  line-height: 1.6;
}

.index-hero-buttons {
  display: flex;
  gap: var(--spacing-m);
  flex-wrap: wrap;
}

.index-hero-image {
  flex: 1;
  min-width: 250px;
  border-radius: 8px;
}

.btn--secondary {
  background-color: transparent;
  border: 2px solid var(--color-accent-on-dark);
  color: var(--color-accent-on-dark);
}

.btn--secondary:hover {
  background-color: var(--color-accent-on-dark);
  color: var(--color-primary-dark);
}

.index-highlights {
  background-color: var(--color-white);
}

.index-highlights h2 {
  text-align: center;
  margin-bottom: var(--spacing-2xl);
}

.index-highlight-card {
  display: flex;
  flex-direction: column;
}

.index-highlight-card h3 {
  color: var(--color-primary-dark);
}

.index-highlight-card p {
  flex-grow: 1;
}

.index-card-link {
  display: inline-block;
  color: var(--color-primary-dark);
  font-weight: 600;
  margin-top: var(--spacing-m);
  padding-bottom: var(--spacing-s);
  border-bottom: 2px solid var(--color-accent);
  transition: var(--transition);
}

.index-card-link:hover {
  border-bottom-color: var(--color-primary-dark);
}

.index-featured-classes {
  background-color: var(--color-bg);
}

.index-featured-classes h2 {
  text-align: center;
}

.index-section-intro {
  text-align: center;
  color: var(--color-text-light);
  font-size: 1.05rem;
  margin-bottom: var(--spacing-2xl);
}

.index-class-badge {
  display: inline-block;
  background-color: var(--color-primary);
  color: var(--color-white);
  padding: var(--spacing-s) var(--spacing-m);
  border-radius: 20px;
  font-size: 0.85rem;
  font-weight: 600;
  margin-bottom: var(--spacing-m);
}

.index-class-card h3 {
  color: var(--color-primary-dark);
  margin-bottom: var(--spacing-m);
}

.index-class-description {
  flex-grow: 1;
  color: var(--color-text-light);
}

.index-class-teacher {
  margin-top: var(--spacing-m);
  margin-bottom: var(--spacing-s);
  font-size: 0.95rem;
}

.index-class-schedule {
  margin-bottom: 0;
  font-size: 0.95rem;
  color: var(--color-primary);
  font-weight: 600;
}

.index-testimonials {
  background-color: var(--color-white);
}

.index-testimonials h2 {
  text-align: center;
  margin-bottom: var(--spacing-2xl);
}

.index-testimonial-stars {
  color: #ffc107;
  font-size: 1.1rem;
  margin-bottom: var(--spacing-m);
}

.index-testimonial-text {
  font-size: 0.95rem;
  line-height: 1.8;
  margin-bottom: var(--spacing-l);
  color: var(--color-text-light);
  font-style: italic;
}

.index-testimonial-author {
  margin-bottom: 0;
  font-size: 0.9rem;
  color: var(--color-text);
}

.index-cta {
  background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-primary-dark) 100%);
  color: var(--color-accent-on-dark);
}

.index-cta-content {
  text-align: center;
}

.index-cta h2 {
  color: var(--color-accent-on-dark);
  margin-bottom: var(--spacing-l);
}

.index-cta p {
  font-size: 1.1rem;
  margin-bottom: var(--spacing-2xl);
  color: var(--color-accent-on-dark);
}

.index-cta-buttons {
  display: flex;
  gap: var(--spacing-m);
  justify-content: center;
  flex-wrap: wrap;
}

@media (max-width: 600px) {
  .index-hero .container {
    flex-direction: column;
    gap: var(--spacing-l);
  }

  .index-hero-image {
    width: 100%;
  }

  .index-hero h1 {
    font-size: 2rem;
  }

  .index-hero-tagline {
    font-size: 1rem;
  }

  .index-hero-buttons {
    flex-direction: column;
  }

  .index-hero-buttons .btn {
    width: 100%;
  }

  .index-cta-buttons {
    flex-direction: column;
  }

  .index-cta-buttons .btn {
    width: 100%;
  }
}

@media (min-width: 601px) {
  .index-hero .container {
    gap: var(--spacing-xl);
  }
}

.schedule-intro {
  text-align: center;
  font-size: 1.1rem;
  color: var(--color-text-light);
  margin-bottom: var(--spacing-xl);
}

.schedule-wrapper {
  overflow-x: auto;
  margin-bottom: var(--spacing-xl);
  border: 1px solid var(--color-border);
  border-radius: 8px;
  box-shadow: var(--shadow-sm);
}

.schedule-table {
  width: 100%;
  border-collapse: collapse;
  background-color: var(--color-white);
}

.schedule-table thead {
  background-color: var(--color-primary-dark);
  color: var(--color-white);
}

.schedule-table th {
  padding: var(--spacing-m);
  text-align: left;
  font-weight: 600;
  font-family: var(--font-serif);
  font-size: 1rem;
}

.schedule-table td {
  padding: var(--spacing-m);
  border: 1px solid var(--color-border);
  vertical-align: top;
  font-size: 0.95rem;
}

.schedule-table tbody tr:nth-child(even) {
  background-color: rgba(45, 80, 22, 0.02);
}

.schedule-time {
  font-weight: 600;
  color: var(--color-primary-dark);
  white-space: nowrap;
  background-color: rgba(232, 212, 196, 0.3);
}

.schedule-cell {
  display: block;
  line-height: 1.5;
}

.schedule-cell strong {
  color: var(--color-primary-dark);
  display: block;
  margin-bottom: 0.25rem;
}

.schedule-cell small {
  color: var(--color-text-light);
  display: block;
  margin-bottom: 0.5rem;
  font-style: italic;
}

.schedule-level {
  display: inline-block;
  padding: 0.25rem 0.75rem;
  border-radius: 4px;
  font-size: 0.8rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 0.25rem;
}

.schedule-level.beginner {
  background-color: rgba(74, 124, 89, 0.15);
  color: var(--color-primary-dark);
}

.schedule-level.intermediate {
  background-color: rgba(232, 212, 196, 0.4);
  color: var(--color-primary-dark);
}

.schedule-level.advanced {
  background-color: rgba(45, 80, 22, 0.15);
  color: var(--color-primary-dark);
}

.schedule-legend {
  text-align: center;
  padding: var(--spacing-l);
  background-color: rgba(232, 212, 196, 0.15);
  border-radius: 8px;
  border: 1px solid var(--color-border);
}

.schedule-legend p {
  margin-bottom: var(--spacing-m);
}

.schedule-legend p:last-child {
  margin-bottom: 0;
}

.schedule-types-section {
  background-color: rgba(45, 80, 22, 0.04);
}

.class-types-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: var(--spacing-l);
}

.class-type-card {
  background-color: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: 8px;
  padding: var(--spacing-l);
  box-shadow: var(--shadow-sm);
  transition: var(--transition);
}

.class-type-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-4px);
}

.class-type-card h3 {
  color: var(--color-primary-dark);
  margin-bottom: var(--spacing-m);
}

.class-type-level {
  margin-bottom: var(--spacing-m);
}

.class-type-card p {
  margin-bottom: var(--spacing-m);
  color: var(--color-text);
  font-size: 0.95rem;
  line-height: 1.6;
}

.class-type-card p:last-child {
  margin-bottom: 0;
}

.class-type-card strong {
  color: var(--color-primary-dark);
}

@media (max-width: 600px) {
  .schedule-wrapper {
    margin-left: calc(var(--spacing-m) * -1);
    margin-right: calc(var(--spacing-m) * -1);
    border-radius: 0;
  }

  .schedule-table {
    font-size: 0.85rem;
  }

  .schedule-table th,
  .schedule-table td {
    padding: var(--spacing-s);
  }

  .schedule-cell small {
    font-size: 0.75rem;
  }

  .schedule-level {
    font-size: 0.7rem;
    padding: 0.2rem 0.5rem;
  }

  .class-types-grid {
    grid-template-columns: 1fr;
    gap: var(--spacing-m);
  }

  .schedule-legend {
    padding: var(--spacing-m);
  }
}

@media (min-width: 601px) {
  .schedule-table tbody tr:hover {
    background-color: rgba(45, 80, 22, 0.05);
  }
}

.teacher-card {
  display: flex;
  flex-direction: column;
  height: 100%;
}

.teacher-card img {
  width: 100%;
  height: 280px;
  object-fit: cover;
  margin-bottom: var(--spacing-m);
  border-radius: 8px;
}

.teacher-card h3 {
  margin-bottom: var(--spacing-s);
}

.teacher-cert {
  font-size: 0.9rem;
  color: var(--color-text-light);
  font-weight: 600;
  margin-bottom: var(--spacing-s);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.teacher-specialty {
  font-size: 0.95rem;
  color: var(--color-primary);
  margin-bottom: var(--spacing-m);
  font-weight: 500;
}

.teacher-card p:last-child {
  margin-bottom: 0;
  flex-grow: 1;
  font-size: 0.95rem;
  line-height: 1.7;
}

.teachers-philosophy {
  background-color: var(--color-primary-dark);
  color: var(--color-accent-on-dark);
}

.teachers-philosophy h2 {
  color: var(--color-accent-on-dark);
}

.teachers-philosophy p {
  color: var(--color-accent-on-dark);
  font-size: 1.05rem;
  line-height: 1.8;
}

.philosophy-list {
  list-style: none;
  padding: 0;
  margin: var(--spacing-l) 0 0 0;
}

.philosophy-list li {
  padding: var(--spacing-m) 0;
  padding-left: var(--spacing-l);
  position: relative;
  color: var(--color-accent-on-dark);
  font-size: 1.05rem;
  line-height: 1.7;
}

.philosophy-list li::before {
  content: "✓";
  position: absolute;
  left: 0;
  top: var(--spacing-m);
  color: var(--color-accent);
  font-weight: bold;
  font-size: 1.25rem;
}

@media (max-width: 600px) {
  .teacher-card img {
    height: 240px;
  }

  .teachers-philosophy {
    padding: var(--spacing-xl) 0;
  }
}

.pricing-intro {
  text-align: center;
  font-size: 1.1rem;
  color: var(--color-text-light);
  margin-bottom: var(--spacing-2xl);
}

.pricing-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: var(--spacing-l);
  margin-bottom: var(--spacing-2xl);
}

.pricing-card {
  background-color: var(--color-white);
  border: 2px solid var(--color-border);
  border-radius: 8px;
  padding: var(--spacing-l);
  display: flex;
  flex-direction: column;
  transition: var(--transition);
  position: relative;
}

.pricing-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-8px);
  border-color: var(--color-primary);
}

.pricing-card--featured {
  border-color: var(--color-primary);
  box-shadow: var(--shadow-md);
  transform: scale(1.05);
}

.pricing-card--featured:hover {
  transform: scale(1.05) translateY(-8px);
}

.pricing-badge {
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background-color: var(--color-success);
  color: var(--color-white);
  padding: var(--spacing-s) var(--spacing-m);
  border-radius: 20px;
  font-size: 0.85rem;
  font-weight: 600;
  white-space: nowrap;
}

.pricing-card h3 {
  color: var(--color-primary-dark);
  margin-bottom: var(--spacing-m);
  margin-top: var(--spacing-m);
}

.pricing-card--featured h3 {
  color: var(--color-primary);
}

.pricing-price {
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--color-primary-dark);
  margin-bottom: var(--spacing-s);
  line-height: 1;
}

.pricing-unit {
  display: block;
  font-size: 0.75rem;
  color: var(--color-text-light);
  font-weight: 400;
  margin-top: var(--spacing-s);
}

.pricing-description {
  font-size: 0.95rem;
  color: var(--color-text-light);
  margin-bottom: var(--spacing-m);
  flex-grow: 1;
}

.pricing-features {
  list-style: none;
  margin-bottom: var(--spacing-l);
  flex-grow: 1;
}

.pricing-features li {
  padding: var(--spacing-s) 0;
  padding-left: 1.5rem;
  position: relative;
  color: var(--color-text);
  font-size: 0.95rem;
}

.pricing-features li:before {
  content: "✓";
  position: absolute;
  left: 0;
  color: var(--color-success);
  font-weight: 700;
  font-size: 1.1rem;
}

.pricing-btn {
  margin-top: auto;
  width: 100%;
  justify-content: center;
}

.pricing-offers {
  background-color: #f0f3eb;
  padding: var(--spacing-2xl) 0;
}

.offers-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: var(--spacing-l);
}

.offer-card {
  background-color: var(--color-white);
  border-left: 4px solid var(--color-primary);
  border-radius: 4px;
  padding: var(--spacing-l);
  box-shadow: var(--shadow-sm);
}

.offer-card h3 {
  color: var(--color-primary-dark);
  margin-bottom: var(--spacing-m);
}

.offer-card p {
  color: var(--color-text);
  font-size: 0.95rem;
  line-height: 1.7;
}

.pricing-faq {
  padding: var(--spacing-2xl) 0;
}

.pricing-faq h2 {
  margin-bottom: var(--spacing-2xl);
  text-align: center;
}

.faq-item {
  background-color: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: 6px;
  margin-bottom: var(--spacing-l);
  padding: 0;
  overflow: hidden;
}

.faq-item summary {
  cursor: pointer;
  padding: var(--spacing-l);
  display: flex;
  align-items: center;
  justify-content: space-between;
  user-select: none;
  transition: var(--transition);
}

.faq-item summary:hover {
  background-color: #f5f5f5;
}

.faq-item summary h3 {
  margin: 0;
  color: var(--color-primary-dark);
  font-size: 1.1rem;
  flex-grow: 1;
}

.faq-item summary::-webkit-details-marker {
  display: none;
}

.faq-item summary::after {
  content: "+";
  font-size: 1.5rem;
  color: var(--color-primary);
  margin-left: var(--spacing-m);
  min-width: 2rem;
  text-align: right;
  transition: var(--transition);
}

.faq-item[open] summary::after {
  content: "−";
}

.faq-item p {
  padding: 0 var(--spacing-l) var(--spacing-l) var(--spacing-l);
  color: var(--color-text);
  line-height: 1.8;
  margin-bottom: 0;
}

@media (max-width: 600px) {
  .pricing-card--featured {
    transform: scale(1);
  }

  .pricing-card--featured:hover {
    transform: translateY(-8px);
  }

  .pricing-price {
    font-size: 2rem;
  }

  .faq-item summary {
    flex-direction: column;
    align-items: flex-start;
  }

  .faq-item summary::after {
    margin-left: 0;
    margin-top: var(--spacing-s);
  }
}

@media (min-width: 601px) {
  .pricing-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .pricing-grid > :nth-child(1),
  .pricing-grid > :nth-child(4) {
    grid-column: span 1;
  }

  .pricing-card--featured {
    grid-column: 2;
    grid-row: span 2;
  }
}

.contact-section {
  padding: var(--spacing-2xl) 0;
}

.contact-wrapper {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--spacing-2xl);
  align-items: start;
}

.contact-form-wrapper {
  background-color: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: 8px;
  padding: var(--spacing-l);
  box-shadow: var(--shadow-sm);
}

.contact-form-wrapper h2 {
  margin-bottom: var(--spacing-m);
}

.contact-form-wrapper p {
  margin-bottom: var(--spacing-l);
  color: var(--color-text-light);
}

.form-group {
  margin-bottom: var(--spacing-m);
}

.form-group label {
  display: block;
  margin-bottom: var(--spacing-s);
  font-weight: 600;
  color: var(--color-text);
}

.form-group input,
.form-group select,
.form-group textarea {
  width: 100%;
  padding: var(--spacing-m);
  border: 1px solid var(--color-border);
  border-radius: 4px;
  font-family: var(--font-sans);
  font-size: 1rem;
  background-color: var(--color-white);
  color: var(--color-text);
  transition: var(--transition);
  min-height: 44px;
}

.form-group input:focus,
.form-group select:focus,
.form-group textarea:focus {
  outline: 2px solid var(--color-accent);
  outline-offset: 1px;
  border-color: var(--color-primary);
}

.form-group textarea {
  resize: vertical;
  min-height: 120px;
}

.contact-info-wrapper {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-l);
}

.contact-info-wrapper h2 {
  margin-top: 0;
}

.contact-details {
  background-color: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: 8px;
  padding: var(--spacing-l);
  box-shadow: var(--shadow-sm);
}

.contact-details h3 {
  margin-top: 0;
  margin-bottom: var(--spacing-m);
  font-size: 1.25rem;
}

.contact-details address {
  font-style: normal;
}

.contact-details p {
  margin-bottom: var(--spacing-m);
  line-height: 1.8;
}

.contact-details p:last-child {
  margin-bottom: 0;
}

.contact-details a {
  color: var(--color-primary);
  font-weight: 500;
  text-decoration: none;
}

.contact-details a:hover {
  color: var(--color-primary-dark);
  text-decoration: underline;
}

.contact-hours {
  list-style: none;
  padding: 0;
}

.contact-hours li {
  padding: var(--spacing-s) 0;
  line-height: 1.8;
  border-bottom: 1px solid var(--color-border);
}

.contact-hours li:last-child {
  border-bottom: none;
}

.contact-map {
  background-color: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: 8px;
  padding: var(--spacing-l);
  box-shadow: var(--shadow-sm);
}

.contact-map h3 {
  margin-top: 0;
  margin-bottom: var(--spacing-m);
}

.contact-map iframe {
  border-radius: 4px;
  max-width: 100%;
}

.contact-faq {
  padding: var(--spacing-2xl) 0;
}

.contact-faq h2 {
  margin-bottom: var(--spacing-xl);
  color: var(--color-primary-dark);
}

.contact-faq-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: var(--spacing-l);
}

.contact-faq-item {
  background-color: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: 8px;
  padding: var(--spacing-l);
  box-shadow: var(--shadow-sm);
  cursor: pointer;
}

.contact-faq-item summary {
  list-style: none;
  cursor: pointer;
  font-weight: 600;
  display: flex;
  align-items: center;
  justify-content: space-between;
  user-select: none;
}

.contact-faq-item summary::after {
  content: '▼';
  display: inline-block;
  margin-left: var(--spacing-m);
  transition: var(--transition);
  flex-shrink: 0;
}

.contact-faq-item[open] summary::after {
  transform: rotate(-180deg);
}

.contact-faq-item summary h4 {
  margin: 0;
  font-size: 1.1rem;
}

.contact-faq-item summary:focus {
  outline: 2px solid var(--color-primary);
  outline-offset: 2px;
}

.contact-faq-item p {
  margin-top: var(--spacing-m);
  margin-bottom: 0;
  color: var(--color-text-light);
  line-height: 1.8;
}

.contact-faq-item p a {
  color: var(--color-primary);
  text-decoration: none;
  font-weight: 500;
}

.contact-faq-item p a:hover {
  text-decoration: underline;
}

@media (max-width: 600px) {
  .contact-wrapper {
    grid-template-columns: 1fr;
    gap: var(--spacing-xl);
  }

  .contact-form-wrapper,
  .contact-details,
  .contact-map {
    padding: var(--spacing-l);
  }

  .contact-map iframe {
    height: 250px;
  }

  .contact-faq-grid {
    grid-template-columns: 1fr;
    gap: var(--spacing-m);
  }

  .contact-faq-item {
    padding: var(--spacing-m);
  }

  .contact-faq-item summary h4 {
    font-size: 1rem;
  }
}

final.css:
:root {
  --color-primary: #2d5016;
  --color-primary-dark: #1f3810;
  --color-accent: #e8d4c4;
  --color-accent-on-dark: #f5e6dd;
  --color-text: #2b2b2b;
  --color-text-light: #6b6b6b;
  --color-bg: #fafbf8;
  --color-border: #d4ccc0;
  --color-success: #4a7c59;
  --color-white: #ffffff;
  --font-serif: Georgia, "Times New Roman", serif;
  --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Arial, sans-serif;
  --spacing-unit: 1rem;
  --spacing-s: calc(var(--spacing-unit) * 0.5);
  --spacing-m: var(--spacing-unit);
  --spacing-l: calc(var(--spacing-unit) * 2);
  --spacing-xl: calc(var(--spacing-unit) * 3);
  --spacing-2xl: calc(var(--spacing-unit) * 4);
  --shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px rgba(0, 0, 0, 0.1);
  --shadow-lg: 0 10px 20px rgba(0, 0, 0, 0.15);
  --transition: all 0.3s ease;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-sans);
  color: var(--color-text);
  background-color: var(--color-bg);
  line-height: 1.6;
  font-size: 1rem;
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-serif);
  font-weight: 600;
  line-height: 1.3;
  margin-bottom: var(--spacing-m);
  color: var(--color-primary-dark);
}

h1 { font-size: clamp(2rem, 5vw, 3.5rem); }
h2 { font-size: clamp(1.75rem, 4vw, 2.75rem); }
h3 { font-size: clamp(1.25rem, 3vw, 1.75rem); }
h4 { font-size: 1.25rem; }
h5 { font-size: 1.1rem; }
h6 { font-size: 1rem; }

p {
  margin-bottom: var(--spacing-m);
}

a {
  color: var(--color-primary);
  text-decoration: underline;
  transition: var(--transition);
}

a:hover {
  color: var(--color-primary-dark);
  text-decoration: underline;
}

a:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
  border-radius: 2px;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 var(--spacing-m);
}

header.site-header {
  background-color: var(--color-white);
  border-bottom: 1px solid var(--color-border);
  position: sticky;
  top: 0;
  z-index: 100;
  box-shadow: var(--shadow-sm);
}

header.site-header .container {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: var(--spacing-m);
  padding-bottom: var(--spacing-m);
  flex-wrap: wrap;
  gap: var(--spacing-m);
}

.logo {
  font-family: "Palatino Linotype", "Book Antiqua", serif;
  font-size: clamp(1.3rem, 4vw, 1.6rem);
  font-weight: 400;
  font-variant: small-caps;
  letter-spacing: 0.15em;
  color: var(--color-primary-dark);
  border-bottom: 2px solid var(--color-accent);
  padding-bottom: 0.25rem;
  white-space: nowrap;
}

.logo:hover {
  color: var(--color-primary);
  text-decoration: none;
}

.logo:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

header nav {
  display: flex;
  gap: var(--spacing-l);
  flex-wrap: wrap;
}

header nav a {
  display: inline-block;
  padding: var(--spacing-s) var(--spacing-m);
  color: var(--color-text);
  font-weight: 500;
  transition: var(--transition);
  border-bottom: 2px solid transparent;
}

header nav a:hover {
  color: var(--color-primary);
  border-bottom-color: var(--color-accent);
  text-decoration: none;
}

header nav a:focus {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}

footer.site-footer {
  background-color: var(--color-primary-dark);
  color: var(--color-accent-on-dark);
  padding: var(--spacing-2xl) var(--spacing-m);
  margin-top: var(--spacing-2xl);
}

footer.site-footer .container {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--spacing-xl);
  align-items: start;
}

footer.site-footer .footer-content {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-l);
}

footer.site-footer p {
  margin-bottom: 0;
  font-size: 0.95rem;
  line-height: 1.8;
}

footer.site-footer a {
  color: var(--color-accent-on-dark);
}

footer.site-footer a:hover {
  color: var(--color-white);
}

footer.site-footer .footer-copyright {
  text-align: center;
  grid-column: 1 / -1;
  font-size: 0.85rem;
  color: rgba(245, 230, 221, 0.7);
  border-top: 1px solid rgba(245, 230, 221, 0.2);
  padding-top: var(--spacing-l);
}

button, input[type="submit"], input[type="reset"], input[type="button"], .btn {
  display: inline-block;
  padding: var(--spacing-m) var(--spacing-l);
  min-height: 44px;
  min-width: 44px;
  background-color: var(--color-primary-dark);
  color: var(--color-white);
  border: none;
  border-radius: 4px;
  font-family: var(--font-sans);
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: var(--transition);
  text-decoration: none;
  text-align: center;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

button:hover, .btn:hover {
  background-color: var(--color-primary);
}

button:focus, .btn:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

button:active, .btn:active {
  transform: scale(0.98);
}

input[type="text"],
input[type="email"],
input[type="tel"],
input[type="password"],
input[type="date"],
input[type="time"],
input[type="number"],
select,
textarea {
  display: block;
  width: 100%;
  padding: var(--spacing-m);
  margin-bottom: var(--spacing-m);
  border: 1px solid var(--color-border);
  border-radius: 4px;
  font-family: var(--font-sans);
  font-size: 1rem;
  background-color: var(--color-white);
  color: var(--color-text);
  transition: var(--transition);
  min-height: 44px;
}

input[type="text"]:focus,
input[type="email"]:focus,
input[type="tel"]:focus,
input[type="password"]:focus,
input[type="date"]:focus,
input[type="time"]:focus,
input[type="number"]:focus,
select:focus,
textarea:focus {
  outline: 2px solid var(--color-accent);
  outline-offset: 1px;
  border-color: var(--color-primary);
}

label {
  display: block;
  margin-bottom: var(--spacing-s);
  font-weight: 600;
  color: var(--color-text);
}

textarea {
  resize: vertical;
  min-height: 120px;
}

.card {
  background-color: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: 8px;
  padding: var(--spacing-l);
  transition: var(--transition);
  box-shadow: var(--shadow-sm);
}

.card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-4px);
}

.grid {
  display: grid;
  gap: var(--spacing-l);
  margin-bottom: var(--spacing-xl);
}

.grid--2col {
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
}

.grid--3col {
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
}

section {
  padding: var(--spacing-2xl) 0;
}

main {
  min-height: calc(100vh - 300px);
}

img {
  max-width: 100%;
  height: auto;
  display: block;
  border-radius: 4px;
}

@media (max-width: 600px) {
  :root {
    --spacing-unit: 0.9rem;
  }

  header.site-header .container {
    flex-direction: column;
    align-items: flex-start;
    padding-top: var(--spacing-m);
    padding-bottom: var(--spacing-m);
  }

  .logo {
    font-size: 1.2rem;
  }

  header nav {
    width: 100%;
    gap: var(--spacing-m);
    flex-direction: column;
  }

  header nav a {
    padding: 0.6rem var(--spacing-s);
    font-size: 0.95rem;
  }

  footer.site-footer .container {
    grid-template-columns: 1fr;
    gap: var(--spacing-l);
  }

  .grid--2col,
  .grid--3col {
    grid-template-columns: 1fr;
  }

  section {
    padding: var(--spacing-xl) 0;
  }

  h1 { font-size: 1.75rem; }
  h2 { font-size: 1.5rem; }
  h3 { font-size: 1.2rem; }

  button, .btn, input[type="submit"] {
    width: 100%;
  }
}

@media (min-width: 601px) {
  header nav {
    margin-left: auto;
  }
}

@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

pages.css:
.index-hero {
  background: linear-gradient(135deg, var(--color-primary-dark) 0%, var(--color-primary) 100%);
  color: var(--color-accent-on-dark);
  padding: var(--spacing-2xl) 0;
}

.index-hero .container {
  display: flex;
  align-items: center;
  gap: var(--spacing-2xl);
}

.index-hero-content {
  flex: 1;
}

.index-hero h1 {
  color: var(--color-accent-on-dark);
  margin-bottom: var(--spacing-l);
}

.index-hero-tagline {
  font-size: 1.15rem;
  color: var(--color-accent-on-dark);
  margin-bottom: var(--spacing-l);
  line-height: 1.6;
}

.index-hero-buttons {
  display: flex;
  gap: var(--spacing-m);
  flex-wrap: wrap;
}

.index-hero-image {
  flex: 1;
  min-width: 250px;
  border-radius: 8px;
}

.btn--secondary {
  background-color: transparent;
  border: 2px solid var(--color-accent-on-dark);
  color: var(--color-accent-on-dark);
}

.btn--secondary:hover {
  background-color: var(--color-accent-on-dark);
  color: var(--color-primary-dark);
}

.index-highlights {
  background-color: var(--color-white);
}

.index-highlights h2 {
  text-align: center;
  margin-bottom: var(--spacing-2xl);
}

.index-highlight-card {
  display: flex;
  flex-direction: column;
}

.index-highlight-card h3 {
  color: var(--color-primary-dark);
}

.index-highlight-card p {
  flex-grow: 1;
}

.index-card-link {
  display: inline-block;
  color: var(--color-primary-dark);
  font-weight: 600;
  margin-top: var(--spacing-m);
  padding-bottom: var(--spacing-s);
  border-bottom: 2px solid var(--color-accent);
  transition: var(--transition);
}

.index-card-link:hover {
  border-bottom-color: var(--color-primary-dark);
}

.index-featured-classes {
  background-color: var(--color-bg);
}

.index-featured-classes h2 {
  text-align: center;
}

.index-section-intro {
  text-align: center;
  color: var(--color-text-light);
  font-size: 1.05rem;
  margin-bottom: var(--spacing-2xl);
}

.index-class-badge {
  display: inline-block;
  background-color: var(--color-primary);
  color: var(--color-white);
  padding: var(--spacing-s) var(--spacing-m);
  border-radius: 20px;
  font-size: 0.85rem;
  font-weight: 600;
  margin-bottom: var(--spacing-m);
}

.index-class-card h3 {
  color: var(--color-primary-dark);
  margin-bottom: var(--spacing-m);
}

.index-class-description {
  flex-grow: 1;
  color: var(--color-text-light);
}

.index-class-teacher {
  margin-top: var(--spacing-m);
  margin-bottom: var(--spacing-s);
  font-size: 0.95rem;
}

.index-class-schedule {
  margin-bottom: 0;
  font-size: 0.95rem;
  color: var(--color-primary);
  font-weight: 600;
}

.index-testimonials {
  background-color: var(--color-white);
}

.index-testimonials h2 {
  text-align: center;
  margin-bottom: var(--spacing-2xl);
}

.index-testimonial-stars {
  color: #ffc107;
  font-size: 1.1rem;
  margin-bottom: var(--spacing-m);
}

.index-testimonial-text {
  font-size: 0.95rem;
  line-height: 1.8;
  margin-bottom: var(--spacing-l);
  color: var(--color-text-light);
  font-style: italic;
}

.index-testimonial-author {
  margin-bottom: 0;
  font-size: 0.9rem;
  color: var(--color-text);
}

.index-cta {
  background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-primary-dark) 100%);
  color: var(--color-accent-on-dark);
}

.index-cta-content {
  text-align: center;
}

.index-cta h2 {
  color: var(--color-accent-on-dark);
  margin-bottom: var(--spacing-l);
}

.index-cta p {
  font-size: 1.1rem;
  margin-bottom: var(--spacing-2xl);
  color: var(--color-accent-on-dark);
}

.index-cta-buttons {
  display: flex;
  gap: var(--spacing-m);
  justify-content: center;
  flex-wrap: wrap;
}

@media (max-width: 600px) {
  .index-hero .container {
    flex-direction: column;
    gap: var(--spacing-l);
  }

  .index-hero-image {
    width: 100%;
  }

  .index-hero h1 {
    font-size: 2rem;
  }

  .index-hero-tagline {
    font-size: 1rem;
  }

  .index-hero-buttons {
    flex-direction: column;
  }

  .index-hero-buttons .btn {
    width: 100%;
  }

  .index-cta-buttons {
    flex-direction: column;
  }

  .index-cta-buttons .btn {
    width: 100%;
  }
}

@media (min-width: 601px) {
  .index-hero .container {
    gap: var(--spacing-xl);
  }
}

.schedule-intro {
  text-align: center;
  font-size: 1.1rem;
  color: var(--color-text-light);
  margin-bottom: var(--spacing-xl);
}

.schedule-wrapper {
  overflow-x: auto;
  margin-bottom: var(--spacing-xl);
  border: 1px solid var(--color-border);
  border-radius: 8px;
  box-shadow: var(--shadow-sm);
}

.schedule-table {
  width: 100%;
  border-collapse: collapse;
  background-color: var(--color-white);
}

.schedule-table thead {
  background-color: var(--color-primary-dark);
  color: var(--color-white);
}

.schedule-table th {
  padding: var(--spacing-m);
  text-align: left;
  font-weight: 600;
  font-family: var(--font-serif);
  font-size: 1rem;
}

.schedule-table td {
  padding: var(--spacing-m);
  border: 1px solid var(--color-border);
  vertical-align: top;
  font-size: 0.95rem;
}

.schedule-table tbody tr:nth-child(even) {
  background-color: rgba(45, 80, 22, 0.02);
}

.schedule-time {
  font-weight: 600;
  color: var(--color-primary-dark);
  white-space: nowrap;
  background-color: rgba(232, 212, 196, 0.3);
}

.schedule-cell {
  display: block;
  line-height: 1.5;
}

.schedule-cell strong {
  color: var(--color-primary-dark);
  display: block;
  margin-bottom: 0.25rem;
}

.schedule-cell small {
  color: var(--color-text-light);
  display: block;
  margin-bottom: 0.5rem;
  font-style: italic;
}

.schedule-level {
  display: inline-block;
  padding: 0.25rem 0.75rem;
  border-radius: 4px;
  font-size: 0.8rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 0.25rem;
}

.schedule-level.beginner {
  background-color: rgba(74, 124, 89, 0.15);
  color: var(--color-primary-dark);
}

.schedule-level.intermediate {
  background-color: rgba(232, 212, 196, 0.4);
  color: var(--color-primary-dark);
}

.schedule-level.advanced {
  background-color: rgba(45, 80, 22, 0.15);
  color: var(--color-primary-dark);
}

.schedule-legend {
  text-align: center;
  padding: var(--spacing-l);
  background-color: rgba(232, 212, 196, 0.15);
  border-radius: 8px;
  border: 1px solid var(--color-border);
}

.schedule-legend p {
  margin-bottom: var(--spacing-m);
}

.schedule-legend p:last-child {
  margin-bottom: 0;
}

.schedule-types-section {
  background-color: rgba(45, 80, 22, 0.04);
}

.class-types-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: var(--spacing-l);
}

.class-type-card {
  background-color: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: 8px;
  padding: var(--spacing-l);
  box-shadow: var(--shadow-sm);
  transition: var(--transition);
}

.class-type-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-4px);
}

.class-type-card h3 {
  color: var(--color-primary-dark);
  margin-bottom: var(--spacing-m);
}

.class-type-level {
  margin-bottom: var(--spacing-m);
}

.class-type-card p {
  margin-bottom: var(--spacing-m);
  color: var(--color-text);
  font-size: 0.95rem;
  line-height: 1.6;
}

.class-type-card p:last-child {
  margin-bottom: 0;
}

.class-type-card strong {
  color: var(--color-primary-dark);
}

@media (max-width: 600px) {
  .schedule-wrapper {
    margin-left: calc(var(--spacing-m) * -1);
    margin-right: calc(var(--spacing-m) * -1);
    border-radius: 0;
  }

  .schedule-table {
    font-size: 0.85rem;
  }

  .schedule-table th,
  .schedule-table td {
    padding: var(--spacing-s);
  }

  .schedule-cell small {
    font-size: 0.75rem;
  }

  .schedule-level {
    font-size: 0.7rem;
    padding: 0.2rem 0.5rem;
  }

  .class-types-grid {
    grid-template-columns: 1fr;
    gap: var(--spacing-m);
  }

  .schedule-legend {
    padding: var(--spacing-m);
  }
}

@media (min-width: 601px) {
  .schedule-table tbody tr:hover {
    background-color: rgba(45, 80, 22, 0.05);
  }
}

.teacher-card {
  display: flex;
  flex-direction: column;
  height: 100%;
}

.teacher-card img {
  width: 100%;
  height: 280px;
  object-fit: cover;
  margin-bottom: var(--spacing-m);
  border-radius: 8px;
}

.teacher-card h3 {
  margin-bottom: var(--spacing-s);
}

.teacher-cert {
  font-size: 0.9rem;
  color: var(--color-text-light);
  font-weight: 600;
  margin-bottom: var(--spacing-s);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.teacher-specialty {
  font-size: 0.95rem;
  color: var(--color-primary);
  margin-bottom: var(--spacing-m);
  font-weight: 500;
}

.teacher-card p:last-child {
  margin-bottom: 0;
  flex-grow: 1;
  font-size: 0.95rem;
  line-height: 1.7;
}

.teachers-philosophy {
  background-color: var(--color-primary-dark);
  color: var(--color-accent-on-dark);
}

.teachers-philosophy h2 {
  color: var(--color-accent-on-dark);
}

.teachers-philosophy p {
  color: var(--color-accent-on-dark);
  font-size: 1.05rem;
  line-height: 1.8;
}

.philosophy-list {
  list-style: none;
  padding: 0;
  margin: var(--spacing-l) 0 0 0;
}

.philosophy-list li {
  padding: var(--spacing-m) 0;
  padding-left: var(--spacing-l);
  position: relative;
  color: var(--color-accent-on-dark);
  font-size: 1.05rem;
  line-height: 1.7;
}

.philosophy-list li::before {
  content: "✓";
  position: absolute;
  left: 0;
  top: var(--spacing-m);
  color: var(--color-accent);
  font-weight: bold;
  font-size: 1.25rem;
}

@media (max-width: 600px) {
  .teacher-card img {
    height: 240px;
  }

  .teachers-philosophy {
    padding: var(--spacing-xl) 0;
  }
}

.pricing-intro {
  text-align: center;
  font-size: 1.1rem;
  color: var(--color-text-light);
  margin-bottom: var(--spacing-2xl);
}

.pricing-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: var(--spacing-l);
  margin-bottom: var(--spacing-2xl);
}

.pricing-card {
  background-color: var(--color-white);
  border: 2px solid var(--color-border);
  border-radius: 8px;
  padding: var(--spacing-l);
  display: flex;
  flex-direction: column;
  transition: var(--transition);
  position: relative;
}

.pricing-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-8px);
  border-color: var(--color-primary);
}

.pricing-card--featured {
  border-color: var(--color-primary);
  box-shadow: var(--shadow-md);
  transform: scale(1.05);
}

.pricing-card--featured:hover {
  transform: scale(1.05) translateY(-8px);
}

.pricing-badge {
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background-color: var(--color-success);
  color: var(--color-white);
  padding: var(--spacing-s) var(--spacing-m);
  border-radius: 20px;
  font-size: 0.85rem;
  font-weight: 600;
  white-space: nowrap;
}

.pricing-card h2 {
  color: var(--color-primary-dark);
  margin-bottom: var(--spacing-m);
  margin-top: var(--spacing-m);
}

.pricing-card--featured h3 {
  color: var(--color-primary);
}

.pricing-price {
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--color-primary-dark);
  margin-bottom: var(--spacing-s);
  line-height: 1;
}

.pricing-unit {
  display: block;
  font-size: 0.75rem;
  color: var(--color-text-light);
  font-weight: 400;
  margin-top: var(--spacing-s);
}

.pricing-description {
  font-size: 0.95rem;
  color: var(--color-text-light);
  margin-bottom: var(--spacing-m);
  flex-grow: 1;
}

.pricing-features {
  list-style: none;
  margin-bottom: var(--spacing-l);
  flex-grow: 1;
}

.pricing-features li {
  padding: var(--spacing-s) 0;
  padding-left: 1.5rem;
  position: relative;
  color: var(--color-text);
  font-size: 0.95rem;
}

.pricing-features li:before {
  content: "✓";
  position: absolute;
  left: 0;
  color: var(--color-success);
  font-weight: 700;
  font-size: 1.1rem;
}

.pricing-btn {
  margin-top: auto;
  width: 100%;
  justify-content: center;
}

.pricing-offers {
  background-color: #f0f3eb;
  padding: var(--spacing-2xl) 0;
}

.offers-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: var(--spacing-l);
}

.offer-card {
  background-color: var(--color-white);
  border-left: 4px solid var(--color-primary);
  border-radius: 4px;
  padding: var(--spacing-l);
  box-shadow: var(--shadow-sm);
}

.offer-card h3 {
  color: var(--color-primary-dark);
  margin-bottom: var(--spacing-m);
}

.offer-card p {
  color: var(--color-text);
  font-size: 0.95rem;
  line-height: 1.7;
}

.pricing-faq {
  padding: var(--spacing-2xl) 0;
}

.pricing-faq h2 {
  margin-bottom: var(--spacing-2xl);
  text-align: center;
}

.faq-item {
  background-color: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: 6px;
  margin-bottom: var(--spacing-l);
  padding: 0;
  overflow: hidden;
}

.faq-item summary {
  cursor: pointer;
  padding: var(--spacing-l);
  display: flex;
  align-items: center;
  justify-content: space-between;
  user-select: none;
  transition: var(--transition);
}

.faq-item summary:hover {
  background-color: #f5f5f5;
}

.faq-item summary h4 {
  margin: 0;
  color: var(--color-primary-dark);
  font-size: 1.1rem;
  flex-grow: 1;
}

.faq-item summary::-webkit-details-marker {
  display: none;
}

.faq-item summary::after {
  content: "+";
  font-size: 1.5rem;
  color: var(--color-primary);
  margin-left: var(--spacing-m);
  min-width: 2rem;
  text-align: right;
  transition: var(--transition);
}

.faq-item[open] summary::after {
  content: "−";
}

.faq-item p {
  padding: 0 var(--spacing-l) var(--spacing-l) var(--spacing-l);
  color: var(--color-text);
  line-height: 1.8;
  margin-bottom: 0;
}

@media (max-width: 600px) {
  .pricing-card--featured {
    transform: scale(1);
  }

  .pricing-card--featured:hover {
    transform: translateY(-8px);
  }

  .pricing-price {
    font-size: 2rem;
  }

  .faq-item summary {
    flex-direction: column;
    align-items: flex-start;
  }

  .faq-item summary::after {
    margin-left: 0;
    margin-top: var(--spacing-s);
  }
}

@media (min-width: 601px) {
  .pricing-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .pricing-grid > :nth-child(1),
  .pricing-grid > :nth-child(4) {
    grid-column: span 1;
  }

  .pricing-card--featured {
    grid-column: 2;
    grid-row: span 2;
  }
}

.contact-section {
  padding: var(--spacing-2xl) 0;
}

.contact-wrapper {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--spacing-2xl);
  align-items: start;
}

.contact-form-wrapper {
  background-color: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: 8px;
  padding: var(--spacing-l);
  box-shadow: var(--shadow-sm);
}

.contact-form-wrapper h2 {
  margin-bottom: var(--spacing-m);
}

.contact-form-wrapper p {
  margin-bottom: var(--spacing-l);
  color: var(--color-text-light);
}

.form-group {
  margin-bottom: var(--spacing-m);
}

.form-group label {
  display: block;
  margin-bottom: var(--spacing-s);
  font-weight: 600;
  color: var(--color-text);
}

.form-group input,
.form-group select,
.form-group textarea {
  width: 100%;
  padding: var(--spacing-m);
  border: 1px solid var(--color-border);
  border-radius: 4px;
  font-family: var(--font-sans);
  font-size: 1rem;
  background-color: var(--color-white);
  color: var(--color-text);
  transition: var(--transition);
  min-height: 44px;
}

.form-group input:focus,
.form-group select:focus,
.form-group textarea:focus {
  outline: 2px solid var(--color-accent);
  outline-offset: 1px;
  border-color: var(--color-primary);
}

.form-group textarea {
  resize: vertical;
  min-height: 120px;
}

.contact-info-wrapper {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-l);
}

.contact-info-wrapper h2 {
  margin-top: 0;
}

.contact-details {
  background-color: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: 8px;
  padding: var(--spacing-l);
  box-shadow: var(--shadow-sm);
}

.contact-details h3 {
  margin-top: 0;
  margin-bottom: var(--spacing-m);
  font-size: 1.25rem;
}

.contact-details address {
  font-style: normal;
}

.contact-details p {
  margin-bottom: var(--spacing-m);
  line-height: 1.8;
}

.contact-details p:last-child {
  margin-bottom: 0;
}

.contact-details a {
  color: var(--color-primary);
  font-weight: 500;
  text-decoration: none;
}

.contact-details a:hover {
  color: var(--color-primary-dark);
  text-decoration: underline;
}

.contact-hours {
  list-style: none;
  padding: 0;
}

.contact-hours li {
  padding: var(--spacing-s) 0;
  line-height: 1.8;
  border-bottom: 1px solid var(--color-border);
}

.contact-hours li:last-child {
  border-bottom: none;
}

.contact-map {
  background-color: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: 8px;
  padding: var(--spacing-l);
  box-shadow: var(--shadow-sm);
}

.contact-map h3 {
  margin-top: 0;
  margin-bottom: var(--spacing-m);
}

.contact-map iframe {
  border-radius: 4px;
  max-width: 100%;
}

.contact-faq {
  padding: var(--spacing-2xl) 0;
}

.contact-faq h2 {
  margin-bottom: var(--spacing-xl);
  color: var(--color-primary-dark);
}

.contact-faq-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: var(--spacing-l);
}

.contact-faq-item {
  background-color: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: 8px;
  padding: var(--spacing-l);
  box-shadow: var(--shadow-sm);
  cursor: pointer;
}

.contact-faq-item summary {
  list-style: none;
  cursor: pointer;
  font-weight: 600;
  display: flex;
  align-items: center;
  justify-content: space-between;
  user-select: none;
}

.contact-faq-item summary::after {
  content: '▼';
  display: inline-block;
  margin-left: var(--spacing-m);
  transition: var(--transition);
  flex-shrink: 0;
}

.contact-faq-item[open] summary::after {
  transform: rotate(-180deg);
}

.contact-faq-item summary h4 {
  margin: 0;
  font-size: 1.1rem;
}

.contact-faq-item summary:focus {
  outline: 2px solid var(--color-primary);
  outline-offset: 2px;
}

.contact-faq-item p {
  margin-top: var(--spacing-m);
  margin-bottom: 0;
  color: var(--color-text-light);
  line-height: 1.8;
}

.contact-faq-item p a {
  color: var(--color-primary);
  text-decoration: none;
  font-weight: 500;
}

.contact-faq-item p a:hover {
  text-decoration: underline;
}

@media (max-width: 600px) {
  .contact-wrapper {
    grid-template-columns: 1fr;
    gap: var(--spacing-xl);
  }

  .contact-form-wrapper,
  .contact-details,
  .contact-map {
    padding: var(--spacing-l);
  }

  .contact-map iframe {
    height: 250px;
  }

  .contact-faq-grid {
    grid-template-columns: 1fr;
    gap: var(--spacing-m);
  }

  .contact-faq-item {
    padding: var(--spacing-m);
  }

  .contact-faq-item summary h4 {
    font-size: 1rem;
  }
}
